#!/usr/bin/env bash
# Evidence: the root-cause-debugging rule is landed in the REPO, not only deployed.
#
# GENERATED BY THIS SCRIPT — it writes its own transcript via `exec >"$OUT"`, so the
# `generated-by` claim is a fact about the file rather than a claim about who typed it.
# Re-run to reproduce:
#
#   bash docs/evidence/land-root-cause-debugging-skill-2026-10-22.sh
#
# READ-ONLY: every command below reads. Nothing is written outside $OUT.
set -uo pipefail

REPO="${REPO:-$HOME/hermes-cortex}"
REL="skills/software-development/root-cause-debugging/SKILL.md"
DEPLOYED="${DEPLOYED:-$HOME/.hermes/skills/software-development/root-cause-debugging/SKILL.md}"
PARITY="$REPO/docs/evidence/skill-drift-parity.txt"
OUT="${OUT:-$REPO/docs/evidence/land-root-cause-debugging-skill-2026-10-22.txt}"
exec >"$OUT" 2>&1

norm() { sed -e "s|$HOME|~|g" -e $'s/\033\\[[0-9;]*m//g'; }
say()  { printf '%s\n' "$*"; }
rule() { printf '%s\n' "────────────────────────────────────────────────────────────"; }

say "land the root-cause-debugging rule — evidence"
say "captured-at : $(cd "$REPO" && git rev-parse --short HEAD)  (the working tree's revision)"
say "generated-by: docs/evidence/land-root-cause-debugging-skill-2026-10-22.sh (this file wrote itself)"
rule

say ""
say "1. WHY this cycle exists"
say "   The rule was added to the DEPLOYED skill during cycle 13608. The REPO tree is"
say "   canonical, so a deployed-only edit is fragile: the next sync can revert it and the"
say "   lesson is lost to the whole fleet. A lesson that exists on one host only is not a"
say "   lesson, it is local state."
rule

say ""
say "2. The rule is present in BOTH copies — same content, proven by hash not by eye"
say "   \$ grep -c 'absent CALLER is not an absent WRITER'  <each copy>"
say "     repo     : $(grep -c 'absent CALLER is not an absent WRITER' "$REPO/$REL")"
say "     deployed : $(grep -c 'absent CALLER is not an absent WRITER' "$DEPLOYED")"
say "   sha256:"
say "     repo     : $(sha256sum "$REPO/$REL" | cut -c1-64)"
say "     deployed : $(sha256sum "$DEPLOYED" | cut -c1-64)"
if cmp -s "$REPO/$REL" "$DEPLOYED"; then
  say "   cmp -s: IDENTICAL — the repo copy is now what the deployed copy carries."
else
  say "   cmp -s: DIFFER — the copies are not byte-identical; inspect before closing."
fi
rule

say ""
say "3. The sanctioned reconcile path (not a hand-copy by judgement)"
say "   The verdict for THIS file, MEASURED BEFORE the copy was applied in this cycle:"
say "     SUPERSET software-development/root-cause-debugging/SKILL.md:"
say "       pure superset (+28, -0) -> safe to apply"
say "   A PURE SUPERSET means the deployed copy only ADDS lines — it drops nothing, so landing"
say "   it cannot lose repo content. --apply was deliberately NOT used: it would land every"
say "   other safe superset on the host too (8+ files), and this cycle's declared range is this"
say "   file alone. The other stranded skills keep their own disposition."
say ""
say "   Re-running the detector NOW is the same fact from the other side. The file is GONE from"
say "   the stranded list, so an EMPTY grep below is the EXPECTED result, not a broken probe:"
_rs="$(mktemp "${TMPDIR:-/tmp}/reconcile-now.XXXXXX")"
python3 "$REPO/ops/scripts/manage/reconcile-stranded-skills.py" >"$_rs" 2>&1
say "   \$ ... | grep 'Detector verdict'"
grep "Detector verdict" "$_rs" | norm | sed 's/^/     /'
say "   \$ ... | grep -i root-cause"
_rsg="$(grep -i "root-cause" "$_rs" || true)"
if [[ -n "$_rsg" ]]; then printf '%s\n' "$_rsg" | norm | sed 's/^/     /';
else say "     (no output — not stranded: this cycle's result)"; fi
rm -f "$_rs"
rule

say ""
say "4. The drift record no longer lists this file — the point of the cycle"
say "   \$ grep -c 'root-cause-debugging' docs/evidence/skill-drift-parity.txt"
say "     before this cycle : 1   (listed at line 48, as a stranded/divergent skill)"
say "     after  regenerating the record : $(grep -c 'root-cause-debugging' "$PARITY")"
say ""
say "   The record is regenerated with its own documented command:"
say "   \$ python3 ops/scripts/manage/check-skill-drift-parity.py"
say "     exit rc=1 still — 17 OTHER skills remain stranded, which is pre-existing and NOT"
say "     this cycle's scope. THIS file is resolved."
rule

say ""
say "5. What this capture covers"
say "   UNCOMMITTED at capture time — the committed copy lands one commit after this run."
say "   HEAD at capture: $(cd "$REPO" && git rev-parse --short HEAD)"
(cd "$REPO" && git status --short -- "$REL" docs/evidence/skill-drift-parity.txt docs/evidence/land-root-cause-debugging-skill-2026-10-22.sh docs/evidence/land-root-cause-debugging-skill-2026-10-22.txt | norm | sed 's/^/     /')
rule
say ""
say "end of evidence"
